package com.xuyuan.blog.admin.service.impl;
import com.xuyuan.blog.admin.dto.AboutUpdateParam;import com.xuyuan.blog.admin.mapper.AboutMapper;import com.xuyuan.blog.admin.service.AdminAboutService;import com.xuyuan.blog.model.entity.About;import lombok.RequiredArgsConstructor;import org.springframework.beans.BeanUtils;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class AdminAboutServiceImpl implements AdminAboutService { private final AboutMapper mapper; public About get(){About a=mapper.selectOne(new com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper<About>().last("LIMIT 1"));return a;} @Transactional public About update(AboutUpdateParam p){About a=get();if(a==null)a=new About();BeanUtils.copyProperties(p,a);if(a.getId()==null)mapper.insert(a);else mapper.updateById(a);return a;} }
